import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, it } from "node:test";
import {
  CONTRACT_STATUS,
  classifyHttpReply,
  parseHandoffReply,
  parseLookupReply,
  parseRedemptionReply,
  parseStatusReply,
  parseUsualCoffeeReply,
  type HandoffClaim,
} from "../../src/staff/redemptionRecovery/wire";

/*
 * UI-04G — cross-language contract tests. The vectors are GENERATED by the
 * real PHP services + response mappers (wordpress/evangelou-club/tests/bin/
 * write-contract-vectors.php; a PHP unit test fails on drift) and are fed,
 * unchanged, into the strict TypeScript parsers the staff app uses. A
 * mismatch is fixed at the boundary that is wrong — never by loosening a
 * parser.
 */

type Surface = "redemption" | "handoff" | "status" | "lookup" | "usual";
interface Vector {
  name: string;
  surface: Surface;
  http_status: number;
  sent: Record<string, string> | [];
  body: unknown;
  expect: Record<string, string | boolean>;
}

const appDir = process.env.EVC_APP_DIR ?? process.cwd();
const fixture = JSON.parse(
  readFileSync(join(appDir, "..", "wordpress", "evangelou-club", "tests", "fixtures", "contract", "vectors.json"), "utf8"),
) as { schema: string; http_map: Record<string, Record<string, number>>; vectors: Vector[] };
const vectors = fixture.vectors;

function sentOf(v: Vector): Record<string, string> {
  return Array.isArray(v.sent) ? {} : v.sent;
}

/** Runs one vector through the parser of its surface; null/unavailable = rejected. */
function parse(v: Vector): { kind: string; [k: string]: unknown } | null {
  const s = sentOf(v);
  switch (v.surface) {
    case "redemption":
      return parseRedemptionReply(v.body, { requestId: s.request_id, memberId: s.member_id });
    case "handoff":
      return parseHandoffReply(v.body, { handoffRequestId: s.handoff_request_id, redemptionRequestId: s.redemption_request_id, claim: s.claim as HandoffClaim });
    case "status": {
      const r = parseStatusReply(v.body, { redemptionRequestId: s.redemption_request_id, memberId: s.member_id });
      return r.kind === "unavailable" ? null : r;
    }
    case "lookup":
      return parseLookupReply(v.body);
    case "usual":
      return parseUsualCoffeeReply(v.body);
  }
}

const positives = vectors.filter((v) => v.expect.kind !== "invalid");
const negatives = vectors.filter((v) => v.expect.kind === "invalid");

describe("contract vectors (PHP mappers -> TS parsers)", () => {
  it("is the generated fixture with the minimum case set", () => {
    assert.equal(fixture.schema, "evc-contract-vectors-v1");
    assert.ok(positives.length >= 40, `positives: ${positives.length}`);
    assert.ok(negatives.length >= 18, `negatives: ${negatives.length}`);
    const names = new Set(vectors.map((v) => v.name));
    for (const required of [
      "redemption fresh commit",
      "redemption exact replay, unconfirmed",
      "redemption replay on a later Athens day",
      "redemption replay after handoff",
      "handoff first confirmation (handed now)",
      "handoff exact replay",
      "handoff already handed earlier (no invented time)",
      "redemption unknown commit",
      "redemption server error",
      "redemption unknown member",
      "redemption invalid coffee",
      "redemption expired membership",
      "redemption second coffee same day",
      "redemption record integrity failure",
      "NEG redeemed_at without microseconds",
      "NEG redemption wrong request id",
      "NEG redemption wrong member id",
      "NEG redemption extra field",
      "NEG redemption missing field",
      "NEG replay that says prepare",
    ]) {
      assert.ok(names.has(required), `missing vector: ${required}`);
    }
    for (const surface of ["redemption", "handoff", "status", "lookup", "usual"]) {
      assert.ok(negatives.some((v) => v.surface === surface), `no negative vector for ${surface}`);
    }
  });

  for (const v of positives) {
    it(`accepts: ${v.name}`, () => {
      // Every PHP domain body is handed to the parser, whatever its HTTP status.
      const routed = classifyHttpReply(v.surface, v.http_status, v.body);
      assert.equal(routed.kind, "domain");
      const r = parse(v);
      assert.ok(r, `parser rejected a body produced by the PHP mapper: ${JSON.stringify(v.body)}`);
      assert.equal(r.kind, v.expect.kind);
      const e = v.expect;
      if (v.surface === "redemption" && r.kind === "redeemed") {
        assert.equal(e.instruction, "prepare");
        assert.equal(v.http_status, 201);
      }
      if (v.surface === "redemption" && r.kind === "replayed") {
        assert.equal(r.instruction, e.instruction);
        assert.equal(r.fulfillment, e.fulfillment);
        assert.notEqual(r.instruction, "prepare");
      }
      if (r.kind === "refused" || r.kind === "unresolved") assert.equal(r.code, e.code);
      if (v.surface === "redemption" && r.kind === "unresolved") {
        // An uncertain commit is never a definite failure: 503 + same-id retry.
        assert.equal(v.http_status, 503);
        assert.equal((v.body as Record<string, unknown>).retry_request_id, sentOf(v).request_id);
      }
      if (v.surface === "handoff" && r.kind === "unresolved") {
        assert.equal(v.http_status, 503);
        assert.equal((v.body as Record<string, unknown>).retry_handoff_request_id, sentOf(v).handoff_request_id);
      }
      if (v.surface === "handoff" && r.kind === "recorded") {
        assert.equal(r.how, e.how);
        const h = r.handoff as { handoffTime: string; handoffAtUtc: string | null; claim: string };
        assert.equal(h.handoffTime, e.handoff_time);
        // An earlier handoff never carries an invented time.
        if (h.claim === "already_handed_earlier") assert.equal(h.handoffAtUtc, null);
      }
      if (v.surface === "status" && r.kind === "found") {
        assert.equal(r.fulfillment, e.fulfillment);
        assert.equal(r.isCurrentBusinessDate, e.is_current_business_date);
      }
      if (v.surface === "lookup" && r.kind === "found") {
        assert.deepEqual(Object.keys((v.body as { member: object }).member).sort(), ["lookup_ref", "lookup_ref_expires_at_utc", "member_public_id"]);
      }
    });
  }

  for (const v of negatives) {
    it(`rejects: ${v.name}`, () => {
      assert.equal(parse(v), null);
    });
  }

  it("rejects every positive body when replayed against another request or member", () => {
    const other = "6f9619ff-8b86-4011-b42d-00c04fc964ff";
    for (const v of positives.filter((x) => x.surface === "redemption")) {
      assert.equal(parseRedemptionReply(v.body, { requestId: other, memberId: sentOf(v).member_id }), null, v.name);
    }
    for (const v of positives.filter((x) => x.surface === "handoff")) {
      const s = sentOf(v);
      assert.equal(parseHandoffReply(v.body, { handoffRequestId: other, redemptionRequestId: s.redemption_request_id, claim: s.claim as HandoffClaim }), null, v.name);
    }
    for (const v of positives.filter((x) => x.surface === "redemption" && (x.expect.kind === "redeemed" || x.expect.kind === "replayed"))) {
      assert.equal(parseRedemptionReply(v.body, { requestId: sentOf(v).request_id, memberId: "mem_fedcba9876543210fedcba9876543210" }), null, v.name);
    }
  });
});

describe("classifyHttpReply (v1 transport envelope vs v2 domain body)", () => {
  it("mirrors the PHP status map exactly", () => {
    assert.deepEqual(CONTRACT_STATUS, fixture.http_map);
  });

  it("maps the v1 error envelope to a transport failure, never to a domain outcome", () => {
    const env = (code: string) => ({ error: { code, message: "x" } });
    assert.deepEqual(classifyHttpReply("redemption", 401, env("unauthorized")), { kind: "transport", failure: "unauthorized" });
    assert.deepEqual(classifyHttpReply("redemption", 403, env("forbidden")), { kind: "transport", failure: "forbidden" });
    assert.deepEqual(classifyHttpReply("lookup", 429, env("rate_limited")), { kind: "transport", failure: "rate_limited" });
    assert.deepEqual(classifyHttpReply("redemption", 503, env("server_error")), { kind: "transport", failure: "unavailable" });
    assert.deepEqual(classifyHttpReply("status", 500, env("server_error")), { kind: "transport", failure: "unavailable" });
    // An error key wins even next to domain-looking keys.
    assert.deepEqual(classifyHttpReply("redemption", 201, { error: { code: "forbidden" }, outcome: "redeemed" }), { kind: "transport", failure: "forbidden" });
  });

  it("falls back to the status for a non-JSON or foreign body", () => {
    assert.deepEqual(classifyHttpReply("redemption", 401, "<html>"), { kind: "transport", failure: "unauthorized" });
    assert.deepEqual(classifyHttpReply("redemption", 403, null), { kind: "transport", failure: "forbidden" });
    assert.deepEqual(classifyHttpReply("lookup", 429, {}), { kind: "transport", failure: "rate_limited" });
    assert.deepEqual(classifyHttpReply("redemption", 502, "<html>"), { kind: "transport", failure: "unavailable" });
    assert.deepEqual(classifyHttpReply("redemption", 200, { foo: 1 }), { kind: "transport", failure: "unavailable" });
    assert.deepEqual(classifyHttpReply("redemption", 200, "/**/cb({\"outcome\":\"redeemed\"})"), { kind: "transport", failure: "unavailable" });
    // A WordPress _envelope wrapper: 200 around a failure is never a domain reply.
    assert.deepEqual(classifyHttpReply("redemption", 200, { body: { error: { code: "unauthorized" } }, status: 401, headers: {} }), { kind: "transport", failure: "unavailable" });
    // An unknown error code never borrows the auth meaning of its status.
    assert.deepEqual(classifyHttpReply("redemption", 401, { error: { code: "server_error" } }), { kind: "transport", failure: "unavailable" });
  });

  it("accepts a domain body only with its exact contract status", () => {
    for (const v of positives) {
      const surface = v.surface;
      assert.equal(classifyHttpReply(surface, v.http_status, v.body).kind, "domain", v.name);
      for (const status of [200, 201, 400, 401, 403, 404, 409, 429, 500, 502, 503]) {
        if (status === v.http_status) continue;
        const r = classifyHttpReply(surface, status, v.body);
        assert.equal(r.kind, "transport", `${v.name} with ${status}`);
      }
    }
    // 503 outcome_unknown keeps its same-id retry; the same body on 200/409 is contradictory.
    const unknown = positives.find((v) => v.name === "redemption unknown commit")!.body;
    assert.equal(classifyHttpReply("redemption", 503, unknown).kind, "domain");
    assert.deepEqual(classifyHttpReply("redemption", 200, unknown), { kind: "transport", failure: "unavailable" });
    assert.deepEqual(classifyHttpReply("redemption", 409, unknown), { kind: "transport", failure: "unavailable" });
  });

  it("never accepts 401 as an authenticated domain success", () => {
    for (const v of positives) {
      assert.deepEqual(classifyHttpReply(v.surface, 401, v.body), { kind: "transport", failure: "unauthorized" }, v.name);
    }
  });

  it("never routes a body to the parser of another surface", () => {
    const lookup = positives.find((v) => v.name === "lookup by QR found")!.body;
    const fresh = positives.find((v) => v.name === "redemption fresh commit")!.body;
    assert.equal(classifyHttpReply("lookup", 200, lookup).kind, "domain");
    assert.deepEqual(classifyHttpReply("redemption", 200, lookup), { kind: "transport", failure: "unavailable" });
    assert.deepEqual(classifyHttpReply("lookup", 201, fresh), { kind: "transport", failure: "unavailable" });
    // Prototype keys are not outcomes.
    assert.deepEqual(classifyHttpReply("redemption", 200, { outcome: "constructor" }), { kind: "transport", failure: "unavailable" });
    assert.deepEqual(classifyHttpReply("status", 200, { result: "__proto__" }), { kind: "transport", failure: "unavailable" });
  });
});

describe("parseLookupReply / parseUsualCoffeeReply edge cases", () => {
  const found = positives.find((v) => v.name === "lookup by QR found")!;
  const member = (found.body as { member: Record<string, string> }).member;

  it("rejects a malformed lookup member", () => {
    const withMember = (m: Record<string, unknown>) => ({ result: "found", member: { ...member, ...m } });
    assert.ok(parseLookupReply(withMember({})));
    assert.equal(parseLookupReply(withMember({ member_public_id: "mem_X" })), null);
    assert.equal(parseLookupReply(withMember({ lookup_ref_expires_at_utc: "2026-10-14T07:35:00Z" })), null);
    const [v, kid, payload, sig] = member.lookup_ref.split(".");
    assert.ok(parseLookupReply(withMember({ lookup_ref: [v, kid, payload + "A".repeat(512 - member.lookup_ref.length), sig].join(".") })));
    assert.equal(parseLookupReply(withMember({ lookup_ref: [v, kid, payload + "A".repeat(513 - member.lookup_ref.length), sig].join(".") })), null);
    assert.equal(parseLookupReply(withMember({ lookup_ref: member.lookup_ref + "A" })), null);
    assert.equal(parseLookupReply({ result: "found", member: null }), null);
    assert.equal(parseLookupReply({ result: "not_found", member }), null);
    assert.equal(parseLookupReply({ result: "rate_limited", member: null, retry_after: 5 }), null);
    assert.equal(parseLookupReply({ result: "unknown", member: null }), null);
  });

  it("rejects a malformed usual-coffee suggestion", () => {
    const sug = positives.find((v) => v.name === "usual coffee suggested")!.body as Record<string, unknown>;
    const s = sug.suggestion as Record<string, unknown>;
    const withS = (x: Record<string, unknown>) => ({ ...sug, suggestion: { ...s, ...x } });
    assert.ok(parseUsualCoffeeReply(withS({})));
    assert.equal(parseUsualCoffeeReply(withS({ basis: { occurrences: 4, considered: 3 } })), null);
    assert.equal(parseUsualCoffeeReply(withS({ basis: { occurrences: 0, considered: 3 } })), null);
    assert.equal(parseUsualCoffeeReply(withS({ catalogue_version: 0 })), null);
    assert.equal(parseUsualCoffeeReply(withS({ coffee_code: "Espresso" })), null);
    assert.equal(parseUsualCoffeeReply(withS({ coffee_label: " Espresso" })), null);
    assert.equal(parseUsualCoffeeReply(withS({ modifiers: [{ group: "shots", option: "double", group_label: "Δόση" }] })), null);
    assert.equal(parseUsualCoffeeReply(withS({ modifiers: [{ group: "Shots", option: "double", group_label: "Δόση", label: "Διπλός" }] })), null);
    assert.equal(parseUsualCoffeeReply(withS({ modifiers: [{ group: "shots", option: "double ", group_label: "Δόση", label: "Διπλός" }] })), null);
    assert.equal(parseUsualCoffeeReply(withS({ quick_notes: [{ id: "takeaway", label: "x", text: "free" }] })), null);
    assert.equal(parseUsualCoffeeReply({ ...sug, reason: "no_clear_usual" }), null);
    assert.equal(parseUsualCoffeeReply({ result: "no_suggestion", reason: "free text", suggestion: null, confirmed_order: false }), null);
    assert.equal(parseUsualCoffeeReply({ result: "no_suggestion", reason: "no_clear_usual", suggestion: s, confirmed_order: false }), null);
    assert.equal(parseUsualCoffeeReply({ result: "forbidden", reason: "insufficient_history", suggestion: null, confirmed_order: false }), null);
    assert.equal(parseUsualCoffeeReply({ result: "forbidden", reason: null, suggestion: null }), null);
  });
});
